{
  "grammar_topic": "Preposition",
  "sentence_structure": "S + V + Prep Phrase (at 6:00 P.M.), + Prep + which + S + V + O.",
  "pattern": "time expression + comma + preposition + relative pronoun (which) + clause",
  "vocabulary": [
    {
      "word": "lecture",
      "meaning": "bài thuyết trình, bài giảng",
      "part_of_speech": "noun"
    },
    {
      "word": "attendee",
      "meaning": "người tham dự",
      "part_of_speech": "noun"
    },
    {
      "word": "take place",
      "meaning": "diễn ra",
      "part_of_speech": "verb phrase"
    }
  ],
  "explanation": "Câu hỏi yêu cầu chọn một giới từ thích hợp đi trước đại từ quan hệ 'which' để chỉ thời gian hoặc mối quan hệ logic. Dựa vào ngữ nghĩa của câu, bài giảng sẽ diễn ra lúc 6 giờ chiều, và 'sau' thời điểm đó (after which), những người tham dự có thể đặt câu hỏi. Do đó, 'after' là giới từ chính xác nhất về mặt ngữ nghĩa và ngữ cảnh thời gian.",
  "distractor_analysis": {
    "A": "Giới từ 'across' mang ý nghĩa chỉ vị trí (băng qua, ở phía bên kia), không phù hợp để chỉ thời điểm hoặc mối quan hệ thời gian với mốc 6:00 P.M.",
    "B": "Đáp án đúng. Giới từ 'after' kết hợp với 'which' tạo thành mệnh đề quan hệ chỉ thời gian ('sau khi buổi thuyết trình diễn ra lúc 6:00 P.M.'), hoàn toàn phù hợp với ngữ cảnh người tham dự đặt câu hỏi.",
    "C": "Giới từ 'inside' chỉ vị trí bên trong không gian, không phù hợp với ngữ cảnh thời gian hoặc hành động đặt câu hỏi sau một mốc thời gian.",
    "D": "Giới từ 'among' dùng để chỉ vị trí ở giữa từ ba đối tượng trở lên, không phù hợp để kết hợp với mốc thời gian 6:00 P.M."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Word Form / Adjective",
  "sentence_structure": "S (The _____ antique shop) + V (will close down) + Adv (next month).",
  "pattern": "The + [adjective/determiner] + noun + verb",
  "vocabulary": [
    {
      "word": "antique",
      "meaning": "đồ cổ",
      "part_of_speech": "noun"
    },
    {
      "word": "close down",
      "meaning": "đóng cửa, ngừng hoạt động",
      "part_of_speech": "verb phrase"
    },
    {
      "word": "last",
      "meaning": "cuối cùng",
      "part_of_speech": "adjective"
    }
  ],
  "explanation": "Câu hỏi yêu cầu điền một từ vào vị trí trống trước danh từ 'antique shop' và sau mạo từ 'The'. Cấu trúc này cần một tính từ hoặc từ hạn định để bổ nghĩa cho danh từ. Từ 'last' (cuối cùng) đóng vai trò là từ hạn định/tính từ đứng trước danh từ, phù hợp về mặt ngữ pháp và ngữ nghĩa của câu ('cửa hàng đồ cổ cuối cùng ở Pepper Valley sẽ đóng cửa vào tháng tới').",
  "distractor_analysis": {
    "A": "Đáp án đúng. 'last' là từ hạn định/tính từ đứng trước danh từ 'antique shop' để chỉ cửa hàng cuối cùng.",
    "B": "Sai. 'lasts' là động từ chia ở ngôi thứ ba số ít thì hiện tại đơn, không phù hợp để đứng trước danh từ làm chức năng bổ nghĩa trong ngữ cảnh này.",
    "C": "Sai. 'lasted' là dạng quá khứ hoặc quá khứ phân từ của động từ 'last', không phù hợp về mặt ngữ pháp khi đặt trực tiếp trước danh từ làm tính từ bổ nghĩa theo cách này.",
    "D": "Sai. 'lasting' là phân từ hiện tại/tính từ mang nghĩa 'kéo dài', không phù hợp với ngữ nghĩa 'cửa hàng cuối cùng' của câu."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "vocabulary",
  "sentence_structure": "S + will receive + O (an online status update) + Prep (about the ongoing bridge construction project).",
  "pattern": "receive an online status update",
  "vocabulary": [
    {
      "word": "status",
      "meaning": "tình trạng, trạng thái",
      "part_of_speech": "noun"
    },
    {
      "word": "ongoing",
      "meaning": "đang diễn ra",
      "part_of_speech": "adjective"
    },
    {
      "word": "construction",
      "meaning": "việc xây dựng, công trình xây dựng",
      "part_of_speech": "noun"
    },
    {
      "word": "project",
      "meaning": "dự án",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này kiểm tra từ vựng phù hợp về mặt ngữ nghĩa trong ngữ cảnh thông báo dự án. Danh từ 'update' (bản cập nhật, thông tin mới nhất) kết hợp hoàn hảo với cụm 'online status update' để chỉ việc người dân sẽ nhận được thông tin cập nhật trực tuyến về tình trạng dự án xây dựng cầu đang diễn ra.",
  "distractor_analysis": {
    "A": "Đáp án chính xác. 'update' (bản cập nhật) tạo nên cụm từ có nghĩa tự nhiên 'status update' (bản cập nhật tình trạng) phù hợp với ngữ cảnh thông báo dự án xây dựng.",
    "B": "Đáp án sai về ngữ nghĩa. 'change' (sự thay đổi) không kết hợp tự nhiên với 'status' trong ngữ cảnh nhận thông tin về tiến độ dự án.",
    "C": "Đáp án sai về ngữ nghĩa. 'payment' (sự thanh toán, khoản thanh toán) không phù hợp với ngữ cảnh người dân nhận thông tin trực tuyến về một dự án xây dựng.",
    "D": "Đáp án sai về ngữ nghĩa. 'request' (yêu cầu) không phù hợp vì người dân sẽ nhận được thông tin cập nhật từ cơ quan chức năng chứ không phải nhận một yêu cầu trực tuyến về dự án."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Pronouns",
  "sentence_structure": "Prep (As a result of) + Possessive Determiner (her) + Noun (years) + Participle Phrase (leading media organizations), S (Ms. Ayo) + V (was selected) + Prep (for the Dowel Journalism Prize).",
  "pattern": "As a result of + possessive determiner + noun",
  "vocabulary": [
    {
      "word": "result",
      "meaning": "kết quả",
      "part_of_speech": "noun"
    },
    {
      "word": "leading",
      "meaning": "dẫn dắt, lãnh đạo",
      "part_of_speech": "adjective"
    },
    {
      "word": "media",
      "meaning": "truyền thông",
      "part_of_speech": "noun"
    },
    {
      "word": "selected",
      "meaning": "được lựa chọn",
      "part_of_speech": "verb"
    }
  ],
  "explanation": "Chỗ trống đứng trước cụm danh từ \"many years leading media organizations\" và theo sau cụm giới từ \"As a result of\". Theo ngữ pháp, sau giới từ cần một danh từ hoặc một đại từ sở hữu/tính từ sở hữu làm hạn định từ cho danh từ chính phía sau (\"years\"). Do đó, tính từ sở hữu \"her\" là lựa chọn chính xác để bổ nghĩa cho danh từ \"years\".",
  "distractor_analysis": {
    "A": "Sai vì \"she\" là đại từ nhân xưng đóng vai trò làm chủ ngữ, không thể đứng trước danh từ để làm từ hạn định trong ngữ cảnh này.",
    "B": "Đúng vì \"her\" là tính từ sở hữu, đứng trước danh từ \"many years\" để chỉ sự sở hữu (\"nhiều năm kinh nghiệm dẫn dắt...\").",
    "C": "Sai vì \"hers\" là đại từ sở hữu, đứng độc lập và thay thế cho danh từ chứ không đứng trước một danh từ khác để làm hạn định từ.",
    "D": "Sai vì \"herself\" là đại từ phản thân, thường dùng để nhấn mạnh hoặc khi chủ ngữ và tân ngữ trùng nhau, không phù hợp đứng trước danh từ \"many years\" sau giới từ.",
    "difficulty": "easy"
  }
}

{
  "grammar_topic": "Noun Selection / Vocabulary in Context",
  "sentence_structure": "To (infinitive verb) [the + blank + of + noun], (imperative clause).",
  "pattern": "To stop the [noun] of [noun]",
  "vocabulary": [
    {
      "word": "spread",
      "meaning": "sự lây lan",
      "part_of_speech": "noun"
    },
    {
      "word": "computer virus",
      "meaning": "vi-rút máy tính",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "suspicious",
      "meaning": "đáng ngờ",
      "part_of_speech": "adjective"
    },
    {
      "word": "e-mail",
      "meaning": "thư điện tử",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu hỏi kiểm tra khả năng sử dụng từ vựng phù hợp với ngữ cảnh (vocabulary in context). Vị trí trống cần một danh từ làm tân ngữ cho động từ 'stop' và đứng trước giới từ 'of'. Dựa vào ngữ nghĩa của câu, 'the spread of computer viruses' (sự lây lan của vi-rút máy tính) tạo thành một cụm danh từ có nghĩa logic và tự nhiên nhất khi đi kèm với vế sau 'do not open suspicious e-mails' (đừng mở các email đáng ngờ).",
  "distractor_analysis": {
    "A": "Đáp án A sai vì 'break' (sự bùng nổ, sự nghỉ ngơi) khi kết hợp với 'of computer viruses' không tạo thành cụm từ có nghĩa phù hợp trong ngữ cảnh ngăn chặn mã độc.",
    "B": "Đáp án B là đáp án chính xác. 'Spread' (sự lây lan) kết hợp hoàn hảo với cụm từ chỉ vi-rút máy tính để tạo thành nghĩa hợp lý: ngăn chặn sự lây lan của vi-rút.",
    "C": "Đáp án C sai vì 'balance' có nghĩa là 'sự cân bằng', không phù hợp về mặt ngữ nghĩa khi nói về vi-rút máy tính.",
    "D": "Đáp án D sai vì 'surface' có nghĩa là 'bề mặt', không phù hợp về mặt ý nghĩa ngữ cảnh của câu."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "word form",
  "sentence_structure": "S + (Adv) + V + O",
  "pattern": "subject + adverb + past participle verb + object",
  "vocabulary": [
    {
      "word": "hiring manager",
      "meaning": "người quản lý tuyển dụng",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "applicant",
      "meaning": "ứng viên",
      "part_of_speech": "noun"
    },
    {
      "word": "résumé",
      "meaning": "hồ sơ xin việc",
      "part_of_speech": "noun"
    },
    {
      "word": "qualification",
      "meaning": "trình độ chuyên môn, năng lực",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu yêu cầu điền một trạng từ vào vị trí trước động từ chính 'considered' để bổ nghĩa cho động từ đó. Xét các đáp án, 'carefully' là trạng từ (có đuôi -ly), phù hợp để đứng trước động từ 'considered' diễn tả hành động xem xét một cách cẩn thận.",
  "distractor_analysis": {
    "A": "Sai loại từ. 'caring' là tính từ (hoặc phân từ hiện tại), không phù hợp để bổ nghĩa cho động từ 'considered' ở vị trí này.",
    "B": "Sai loại từ. 'careful' là tính từ, dùng để bổ nghĩa cho danh từ chứ không đứng trước động từ để bổ nghĩa cho hành động.",
    "C": "Đáp án chính xác. 'carefully' là trạng từ, đứng trước động từ quá khứ 'considered' để bổ nghĩa cho hành động xem xét.",
    "D": "Sai loại từ. 'carefulness' là danh từ, không thể đứng ở vị trí trạng từ bổ nghĩa cho động từ."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "conjunction",
  "sentence_structure": "S + V + PrepP + [conj] + V + O",
  "pattern": "V1 + and + V2",
  "vocabulary": [
    {
      "word": "leave",
      "meaning": "rời đi, khởi hành",
      "part_of_speech": "verb"
    },
    {
      "word": "oversee",
      "meaning": "giám sát",
      "part_of_speech": "verb"
    },
    {
      "word": "branch",
      "meaning": "chi nhánh",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu yêu cầu điền một liên từ hoặc trạng từ nối tiếp để liên kết hai hành động của chủ ngữ 'Mr. Sakamoto': 'will leave' (sẽ khởi hành) và 'will oversee' (sẽ giám sát). Đáp án 'and' là liên từ kết hợp phù hợp nhất để nối hai động từ diễn tả các hành động xảy ra tuần tự do cùng một chủ ngữ thực hiện.",
  "distractor_analysis": {
    "A": "because là liên từ chỉ nguyên nhân, không phù hợp về ngữ nghĩa vì hai vế không có quan hệ nguyên nhân - kết quả.",
    "B": "in addition là trạng từ (thường đi với 'to' hoặc đứng đầu câu), không thể dùng trực tiếp để nối hai động từ trong cùng một vị trí ngữ pháp này mà thiếu cấu trúc.",
    "C": "and là liên từ kết hợp chính xác để nối hai động từ 'will leave' và 'will oversee' do cùng một chủ ngữ thực hiện.",
    "D": "prior to là giới từ có nghĩa 'trước khi', không phù hợp với cấu trúc ngữ pháp cần một liên từ nối hai động từ chia theo thì.",
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Noun Collocation / Compound Noun",
  "sentence_structure": "S (Tarateer Pharmaceuticals) + V (is varying) + O (its product [blank]).",
  "pattern": "product line",
  "vocabulary": [
    {
      "word": "vary",
      "meaning": "làm cho khác nhau, thay đổi",
      "part_of_speech": "verb"
    },
    {
      "word": "product",
      "meaning": "sản phẩm",
      "part_of_speech": "noun"
    },
    {
      "word": "line",
      "meaning": "dòng sản phẩm",
      "part_of_speech": "noun"
    },
    {
      "word": "include",
      "meaning": "bao gồm",
      "part_of_speech": "verb"
    }
  ],
  "explanation": "Câu này kiểm tra kiến thức về cụm từ cố định (collocation). Cụm từ 'product line' có nghĩa là 'dòng sản phẩm', rất phổ biến trong tiếng Anh thương mại. Trước chỗ trống là tính từ sở hữu 'its' và danh từ 'product', do đó vị trí cần một danh từ để tạo thành cụm danh từ hoàn chỉnh làm tân ngữ cho động từ 'is varying'. Danh từ số ít 'line' là lựa chọn chính xác.",
  "distractor_analysis": {
    "A": "Sai cấu trúc ngữ pháp và nghĩa. 'to line' là động từ nguyên mẫu có 'to', không phù hợp đứng sau cụm danh từ 'product' trong ngữ cảnh này.",
    "B": "Sai dạng từ. 'lining' là dạng phân từ hiện tại hoặc danh động từ, không tạo thành cụm từ chuẩn với 'product' trong ngữ cảnh chỉ dòng sản phẩm.",
    "C": "Sai dạng từ. 'lined' là dạng phân từ quá khứ hoặc tính từ, không phù hợp để tạo thành cụm danh từ 'product lined' ở đây.",
    "D": "Đáp án chính xác. 'line' là danh từ kết hợp với 'product' tạo thành cụm danh từ 'product line' (dòng sản phẩm), phù hợp về mặt ngữ nghĩa và cấu trúc câu."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Verb Tense and Subject-Verb Agreement",
  "sentence_structure": "S (Dynart, Inc.) + Adv (continuously) + V (_____ new ways) + O (to reduce its use of plastics).",
  "pattern": "Subject + Adverb + Main Verb (Present Simple) + Object",
  "vocabulary": [
    {
      "word": "continuously",
      "meaning": " liên tục, không ngừng",
      "part_of_speech": "adverb"
    },
    {
      "word": "seeks",
      "meaning": " tìm kiếm",
      "part_of_speech": "verb"
    },
    {
      "word": "reduce",
      "meaning": " giảm bớt",
      "part_of_speech": "verb"
    }
  ],
  "explanation": "Câu này thiếu động từ chính cho chủ ngữ số ít 'Dynart, Inc.'. Trạng từ 'continuously' đứng trước vị trí trống để bổ nghĩa cho động từ chính. Do đó, ta cần một động từ chia ở thì hiện tại đơn, dạng số ít (thêm -s) để phù hợp với chủ ngữ ngôi thứ ba số ít. Đáp án 'seeks' là lựa chọn chính xác.",
  "distractor_analysis": {
    "A": "Đáp án chính xác. 'seeks' là động từ chia ở thì hiện tại đơn dạng số ít, phù hợp với chủ ngữ 'Dynart, Inc.' và trạng từ chỉ tần suất/thời gian 'continuously'.",
    "B": "'seeker' là danh từ chỉ người (người tìm kiếm), đặt vào vị trí này sẽ khiến câu thiếu động từ chính.",
    "C": "'to seek' là động từ nguyên mẫu có 'to', không thể đóng vai trò là động từ chính của câu trong cấu trúc này.",
    "D": "'seeking' là phân từ hiện tại hoặc danh động từ, đứng độc lập không thể làm động từ chính cho chủ ngữ 'Dynart, Inc.' nếu không có trợ động từ đi kèm."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Word Form",
